// Un solo formato per i due ingressi: evento Stripe o chiamata manuale.
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.type === 'invoice.upcoming' && j.data && j.data.object) {
    const o = j.data.object;
    const sd = o.subscription_details || (o.parent && o.parent.subscription_details) || {};
    const isSub = !!(o.subscription || (o.parent && o.parent.subscription_details) || o.billing_reason === 'upcoming' || o.billing_reason === 'subscription_cycle');
    if (!isSub) continue; // fattura non da abbonamento: nessun report
    out.push({ json: {
      origine: 'stripe',
      stripe_customer: o.customer || '',
      email: String(o.customer_email || '').trim(),
      nome: String(o.customer_name || '').trim(),
      metaSlug: (sd.metadata && sd.metadata.slug) || (o.metadata && o.metadata.slug) || '',
      slug: '', to: '', dryRun: false,
    } });
  } else {
    const b = j.body || {};
    if (!b.slug) throw new Error('report-invia: manca slug nel body');
    out.push({ json: { origine: 'manuale', stripe_customer: '', email: '', nome: '', metaSlug: '', slug: String(b.slug), to: b.to ? String(b.to) : '', dryRun: !!b.dryRun } });
  }
}
return out;

// Riconosce il cliente del registro. Ordine: id Stripe già memorizzato → slug nei metadati
// dell'abbonamento → e-mail → nome (referente o azienda). Mai un invio se il match è ambiguo.
const n = $('Normalizza').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.slug);
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\([^)]*\)/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const ok = (c, nuovoLink, via) => [{ json: { ...n, trovato: true, nuovoLink, via, cliente: c, slug: c.slug, to: n.to || c.email, nomeSaluto: String(c.referente || '').replace(/\([^)]*\)/g, '').trim() || c.azienda } }];
const ko = motivo => [{ json: { ...n, trovato: false, motivo } }];
if (n.origine === 'manuale') {
  const c = rows.find(r => r.slug === n.slug);
  return c ? ok(c, false, 'slug') : ko('slug sconosciuto nel registro: ' + n.slug);
}
if (n.stripe_customer) {
  const c = rows.filter(r => r.stripe_customer === n.stripe_customer);
  if (c.length === 1) return ok(c[0], false, 'stripe_customer');
  if (c.length > 1) return ko('lo stesso stripe_customer è su più clienti');
}
if (n.metaSlug) {
  const c = rows.find(r => r.slug === n.metaSlug);
  if (c) return ok(c, true, 'metadata.slug');
}
if (n.email) {
  const e = n.email.toLowerCase();
  const c = rows.filter(r => String(r.email || '').toLowerCase() === e);
  if (c.length === 1) return ok(c[0], true, 'email');
  if (c.length > 1) return ko('e-mail ' + n.email + ' presente su più clienti');
}
if (n.nome) {
  const nn = norm(n.nome);
  const c = rows.filter(r => { const a = norm(r.referente), b = norm(r.azienda); return !!nn && (nn === a || nn === b || (!!a && (a.includes(nn) || nn.includes(a))) || (!!b && (b.includes(nn) || nn.includes(b)))); });
  if (c.length === 1) return ok(c[0], true, 'nome');
  if (c.length > 1) return ko('il nome ' + n.nome + ' combacia con più clienti');
}
return ko('nessun cliente con e-mail ' + (n.email || '?') + ' o nome ' + (n.nome || '?'));

