// Periodo: ultimi 30 giorni fino ad ora (Umami aggiunge da solo il confronto coi 30 precedenti).
// Una riga per ogni interrogazione: il nodo HTTP le esegue tutte con un solo nodo.
const a = $('Abbina').first().json;
const id = a.cliente.umami_id;
if (!id) throw new Error('cliente ' + a.slug + ' senza umami_id nel registro: ripubblica il sito dall\'editor');
const end = Date.now(); const start = end - 30 * 864e5; const prev = start - 30 * 864e5;
const base = 'https://stats.consulbuild.com/api/websites/' + id;
const q = 'startAt=' + start + '&endAt=' + end + '&timezone=Europe%2FRome';
const riga = (tipo, url) => ({ json: { tipo, url, start, end, prev } });
return [
  riga('stats', base + '/stats?' + q),
  riga('referrer', base + '/metrics?type=referrer&limit=20&' + q),
  riga('device', base + '/metrics?type=device&limit=10&' + q),
  riga('path', base + '/metrics?type=path&limit=20&' + q),
];

// Compone oggetto, HTML e testo del report. Solo numeri misurati: le sezioni senza dati si omettono.
const a = $('Abbina').first().json; const c = a.cliente;
const qs = $('Interrogazioni').all().map(i => i.json);
const ds = $('Umami dati').all().map(i => i.json.body);
const dato = t => { const k = qs.findIndex(q => q.tipo === t); return k >= 0 ? ds[k] : null; };
const st = dato('stats') || {}; const cmp = st.comparison || {};
const conta = nodo => $(nodo).all().map(i => i.json).filter(r => r && r.id).length;
const richieste = conta('Lead periodo'), richiestePrec = conta('Lead precedente');
const inizio = new Date(qs[0].start), fine = new Date(qs[0].end);
const LEAD_DAL = new Date('2026-09-06T00:00:00+02:00');
const fmt = d => d.toLocaleDateString('it-IT', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Rome' });
const num = v => new Intl.NumberFormat('it-IT').format(v || 0);
const plur = (v, s, p) => num(v) + ' ' + (v === 1 ? s : p);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const delta = (cur, prev) => {
  cur = cur || 0; prev = prev || 0;
  if (!prev) return cur ? { t: 'primo periodo con dati, nessun confronto', col: '#6b6b66' } : { t: 'stabile', col: '#6b6b66' };
  const p = Math.round((cur - prev) / prev * 100);
  if (p > 0) return { t: '\u25B2 +' + p + '% rispetto ai 30 giorni prima', col: '#1f7a3a' };
  if (p < 0) return { t: '\u25BC ' + p + '% rispetto ai 30 giorni prima', col: '#b3261e' };
  return { t: 'stabile rispetto ai 30 giorni prima', col: '#6b6b66' };
};
const visite = st.visits || 0, visitatori = st.visitors || 0;
// Da dove arrivano: quote sui visitatori (chi non ha provenienza nota è arrivato diretto o da un link)
const cat = { 'Google': 0, 'Altri motori di ricerca': 0, 'Social (Facebook, Instagram\u2026)': 0, 'Altri siti': 0 };
for (const r of (dato('referrer') || [])) {
  const d = String(r.x || '').toLowerCase(); const y = r.y || 0; if (!d) continue;
  if (/google\./.test(d)) cat['Google'] += y;
  else if (/bing|duckduckgo|yahoo|ecosia|qwant/.test(d)) cat['Altri motori di ricerca'] += y;
  else if (/facebook|instagram|fb\.|linkedin|tiktok|whatsapp|t\.co|twitter|x\.com|youtube/.test(d)) cat['Social (Facebook, Instagram\u2026)'] += y;
  else cat['Altri siti'] += y;
}
const conRef = Object.values(cat).reduce((s, v) => s + v, 0);
const diretto = Math.max(visitatori - conRef, 0); const totRef = conRef + diretto;
const quote = (coppie, tot) => coppie.filter(([, v]) => v > 0).sort((x, y) => y[1] - x[1]).map(([k, v]) => [k, Math.round(v / tot * 100)]);
const provenienza = totRef ? quote([['Indirizzo digitato o link diretto', diretto], ...Object.entries(cat)], totRef) : [];
// Con cosa navigano
let mob = 0, pc = 0;
for (const d of (dato('device') || [])) { if (/mobile|tablet/i.test(d.x)) mob += d.y || 0; else pc += d.y || 0; }
const dispositivi = (mob + pc) ? quote([['Smartphone e tablet', mob], ['Computer', pc]], mob + pc) : [];
// Sezioni del sito più viste (etichette parlanti; pagine legali e /grazie escluse)
const ET = { '/': 'Pagina principale', '/#servizi': 'Servizi', '/#lavori': 'Lavori realizzati', '/#processo': 'Come lavoriamo', '/#faq': 'Domande frequenti', '/#contatti': 'Modulo di preventivo', '/#canali': 'Contatti' };
const sezioni = (dato('path') || []).filter(p => ET[p.x]).slice(0, 4).map(p => [ET[p.x], plur(p.y, 'visualizzazione', 'visualizzazioni')]);

const dVisitatori = delta(visitatori, cmp.visitors), dVisite = delta(visite, cmp.visits), dRich = delta(richieste, richiestePrec);
const notaLead = inizio < LEAD_DAL ? 'Conteggio delle richieste attivo dal 6 settembre 2026.' : '';
const periodo = fmt(inizio) + ' \u2013 ' + fmt(fine);
const subject = (c.dominio || c.azienda) + ': ' + plur(visitatori, 'visitatore', 'visitatori') + ' e ' + plur(richieste, 'richiesta di preventivo', 'richieste di preventivo') + ' nell\'ultimo mese';

// ---- HTML: tabelle e stili inline (Gmail, Outlook, Apple Mail); apici singoli negli attributi ----
const F = 'font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;';
const INK = '#1c1c1a', MUTED = '#6b6b66', LINE = '#e5e5e0';
const kpi = (n, l, sotto, d) => '<td class=\'kpi\' width=\'33%\' valign=\'top\' style=\'padding:18px 14px 16px;background:#f7f7f5;\'><div style=\'' + F + 'font-size:36px;line-height:1;font-weight:700;color:' + INK + ';\'>' + num(n) + '</div><div style=\'' + F + 'font-size:14px;font-weight:600;color:' + INK + ';margin-top:10px;\'>' + l + '</div><div style=\'' + F + 'font-size:12px;line-height:1.4;color:' + MUTED + ';margin-top:2px;\'>' + sotto + '</div><div style=\'' + F + 'font-size:12px;line-height:1.4;color:' + d.col + ';margin-top:10px;\'>' + esc(d.t) + '</div></td>';
const titolo = t => '<div style=\'' + F + 'font-size:12px;letter-spacing:.08em;text-transform:uppercase;font-weight:600;color:' + MUTED + ';padding-bottom:10px;border-bottom:1px solid ' + LINE + ';\'>' + t + '</div>';
const barre = (t, righe) => !righe.length ? '' : '<tr><td style=\'padding:32px 0 0;\'>' + titolo(t) + '<table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>' + righe.map(([k, p]) => '<tr><td style=\'' + F + 'font-size:15px;color:' + INK + ';padding:12px 0 4px;\'>' + esc(k) + '</td><td align=\'right\' width=\'48\' style=\'' + F + 'font-size:15px;font-weight:600;color:' + INK + ';padding:12px 0 4px;\'>' + p + '%</td></tr><tr><td colspan=\'2\' style=\'padding:0 0 4px;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'><tr><td width=\'' + p + '%\' style=\'background:' + INK + ';height:6px;line-height:6px;font-size:0;\'>&nbsp;</td><td style=\'background:' + LINE + ';height:6px;line-height:6px;font-size:0;\'>&nbsp;</td></tr></table></td></tr>').join('') + '</table></td></tr>';
const elenco = (t, righe) => !righe.length ? '' : '<tr><td style=\'padding:32px 0 0;\'>' + titolo(t) + '<table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>' + righe.map(([k, v]) => '<tr><td style=\'' + F + 'font-size:15px;color:' + INK + ';padding:11px 0;border-bottom:1px solid ' + LINE + ';\'>' + esc(k) + '</td><td align=\'right\' style=\'' + F + 'font-size:15px;color:' + MUTED + ';padding:11px 0;border-bottom:1px solid ' + LINE + ';white-space:nowrap;\'>' + esc(v) + '</td></tr>').join('') + '</table></td></tr>';
const html = '<!DOCTYPE html><html lang=\'it\'><head><meta charset=\'utf-8\'><meta name=\'viewport\' content=\'width=device-width\'><title>' + esc(subject) + '</title><style>@media only screen and (max-width:480px){.kpi{display:block!important;width:100%!important;box-sizing:border-box;margin-bottom:8px;}}</style></head>'
  + '<body style=\'margin:0;padding:0;background:#efefec;\'>'
  + '<table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\' style=\'background:#efefec;\'><tr><td align=\'center\' style=\'padding:32px 12px;\'>'
  + '<table width=\'600\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\' style=\'max-width:600px;width:100%;background:#ffffff;\'>'
  + '<tr><td style=\'padding:22px 36px;background:' + INK + ';\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'><tr><td style=\'' + F + 'font-size:13px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:#ffffff;\'>ConsulBuild</td><td align=\'right\' style=\'' + F + 'font-size:12px;color:#c9c9c4;\'>Report mensile del sito</td></tr></table></td></tr>'
  + '<tr><td style=\'padding:32px 36px 40px;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'0\' role=\'presentation\'>'
  + '<tr><td><div style=\'' + F + 'font-size:26px;line-height:1.2;font-weight:700;color:' + INK + ';\'>' + esc(c.dominio || c.azienda) + '</div><div style=\'' + F + 'font-size:14px;color:' + MUTED + ';margin-top:6px;\'>' + esc(periodo) + '</div></td></tr>'
  + '<tr><td style=\'padding-top:22px;\'><div style=\'' + F + 'font-size:15px;line-height:1.55;color:' + INK + ';\'>Buongiorno ' + esc(a.nomeSaluto) + ',<br>ecco il riepilogo degli ultimi 30 giorni del sito di ' + esc(c.azienda) + '.</div></td></tr>'
  + '<tr><td style=\'padding-top:26px;\'><table width=\'100%\' cellpadding=\'0\' cellspacing=\'8\' role=\'presentation\'><tr>' + kpi(visitatori, 'Visitatori', 'persone diverse che hanno aperto il sito', dVisitatori) + kpi(visite, 'Visite', 'volte in cui il sito \u00e8 stato aperto', dVisite) + kpi(richieste, richieste === 1 ? 'Richiesta di preventivo' : 'Richieste di preventivo', 'moduli compilati sul sito', dRich) + '</tr></table>' + (notaLead ? '<div style=\'' + F + 'font-size:12px;color:' + MUTED + ';margin-top:8px;\'>' + esc(notaLead) + '</div>' : '') + '</td></tr>'
  + barre('Da dove arrivano i visitatori', provenienza) + barre('Con cosa navigano', dispositivi) + elenco('Sezioni pi\u00f9 viste', sezioni)
  + '</table></td></tr>'
  + '<tr><td style=\'padding:20px 36px 24px;border-top:1px solid ' + LINE + ';\'><div style=\'' + F + 'font-size:12px;line-height:1.6;color:' + MUTED + ';\'>Report automatico di <strong style=\'color:' + INK + ';\'>ConsulBuild</strong> per il sito ' + esc(c.dominio || '') + ' \u00b7 info@consulbuild.com<br>Statistiche raccolte senza cookie, nel rispetto della privacy dei visitatori.</div></td></tr>'
  + '</table></td></tr></table></body></html>';

const rigaTxt = (t, r, suff) => r.length ? '\n' + t.toUpperCase() + '\n' + r.map(([k, v]) => '- ' + k + ': ' + v + suff).join('\n') + '\n' : '';
const text = 'CONSULBUILD \u2014 Report mensile del sito\n' + (c.dominio || c.azienda) + '\n' + periodo + '\n\nBuongiorno ' + a.nomeSaluto + ',\necco il riepilogo degli ultimi 30 giorni del sito di ' + c.azienda + '.\n\n'
  + 'Visitatori (persone diverse): ' + num(visitatori) + ' \u2014 ' + dVisitatori.t + '\nVisite (aperture del sito): ' + num(visite) + ' \u2014 ' + dVisite.t + '\nRichieste di preventivo (moduli compilati): ' + num(richieste) + ' \u2014 ' + dRich.t + '\n' + (notaLead ? notaLead + '\n' : '')
  + rigaTxt('Da dove arrivano i visitatori', provenienza, '%') + rigaTxt('Con cosa navigano', dispositivi, '%') + rigaTxt('Sezioni pi\u00f9 viste', sezioni, '')
  + '\nReport automatico di ConsulBuild per il sito ' + (c.dominio || '') + ' \u00b7 info@consulbuild.com\nStatistiche raccolte senza cookie, nel rispetto della privacy dei visitatori.\n';

return [{ json: { slug: a.slug, azienda: c.azienda, to: a.to, subject, html, text, visite, visitatori, richieste, periodo_inizio: inizio.toISOString(), periodo_fine: fine.toISOString(), dryRun: !!a.dryRun, via: a.via } }];
